import React from 'react';

const listings = [
  { id: 1, title: 'iPhone 12 Pro Max', price: 'EGP 15,000', location: 'Cairo', image: 'https://cdn.mos.cms.futurecdn.net/kSUXaLsWD6dMQuXrSRYMKg.jpg' },
  { id: 2, title: '2 Bedroom Apartment for Rent', price: 'EGP 8,000/month', location: 'Alexandria', image: '/placeholder.svg?height=200&width=300' },
  { id: 3, title: 'Toyota Corolla 2019', price: 'EGP 250,000', location: 'Giza', image: '/placeholder.svg?height=200&width=300' },
  { id: 4, title: 'Leather Sofa Set', price: 'EGP 5,000', location: 'Hurghada', image: '/placeholder.svg?height=200&width=300' },
];

export default function FeaturedListings() {
  return (
    <section className="container mx-auto px-4 py-8">
      <h2 className="text-xl md:text-2xl font-bold mb-4">Featured Listings</h2>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {listings.map((listing) => (
          <div
            key={listing.id}
            className="bg-white rounded-md shadow-md overflow-hidden hover:shadow-lg transition-shadow"
          >
            <img
              src={listing.image}
              alt={listing.title}
              width={300}
              height={200}
              className="w-full h-48 object-cover"
            />
            <div className="p-4">
              <h3 className="font-semibold mb-2 text-sm md:text-base">{listing.title}</h3>
              <p className="text-red-600 font-bold text-sm md:text-base">{listing.price}</p>
              <p className="text-gray-600 text-xs md:text-sm">{listing.location}</p>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
